package apicontract

import (
	"github.com/oberthci/oberth/internal/model"
)

// AdminTools declares the admin service operations.
type AdminTools struct {
	AdminAccessList     Binding[AdminAccessListArgs, GrantPage]          `tool:"admin_access_list" command:"-" summary:"Read approved grant paths for installation materialization." desc:"Read approved grant paths for installation materialization. The installation component uses these facts without returning secret values." access:"unscoped_admin" admin:"access-list" bytes:"131072"`
	AdminAuditRecord    Binding[AdminAuditRecordArgs, Receipt]           `tool:"admin_audit_record" command:"-" summary:"Record an installation administration action." desc:"Record a completed operator lifecycle receipt with public scalar details. Inspect audit_list to verify the receipt." access:"unscoped_admin" mutation:"true" admin:"audit-record" bytes:"131072" check:"audit_list"`
	AdminIdle           Binding[AdminIdleArgs, SystemStatus]             `tool:"admin_idle" command:"-" summary:"Wait for admission to become idle." desc:"Observe whether the selected work is idle without stopping admission. The installation component owns waiting and lifecycle changes." access:"unscoped_admin" admin:"idle" bytes:"131072"`
	AdminPublicIdentity Binding[AdminPublicIdentityArgs, PublicIdentity] `tool:"admin_public_identity" command:"-" summary:"Read named public server identity material." desc:"Read named public server identity material. Use the returned public certificate or key to configure the client." access:"unscoped_admin" admin:"public-identity" bytes:"131072"`
	AdminReadiness      Binding[AdminReadinessArgs, SystemStatus]        `tool:"admin_readiness" command:"-" summary:"Read current service readiness without freezing admission." desc:"Read current service readiness without freezing admission. Retry unavailable work after its reported remedy." access:"unscoped_admin" admin:"readiness" bytes:"131072"`
	AdminVersion        Binding[AdminVersionArgs, SystemStatus]          `tool:"admin_version" command:"-" summary:"Read the server and state-schema versions." desc:"Read the server and state-schema versions. Use these facts when planning an installation change." access:"unscoped_admin" admin:"version" bytes:"131072"`
	AuditList           Binding[AuditListArgs, AuditPage]                `tool:"audit_list" command:"audit" flow:"true" summary:"Read authorized audit records in order." desc:"Read operator action receipts in the authorized audit window. Continue older entries with the returned cursor." access:"repository_admin" get:"/api/audit"`
	ClientRenew         Binding[ClientRenewArgs, Identity]               `tool:"client_renew" command:"renew" flow:"true" summary:"Renew the current client certificate." desc:"Renew the caller certificate using a locally generated signing request. Install the returned certificate before reconnecting." mutation:"true" check:"uplink_list"`
	RepoAdd             Binding[RepoAddArgs, Repository]                 `tool:"repo_add" summary:"Register a repository and its upstream." desc:"Register a repository with its named upstream and default branch. Use repo_verify to probe access before pushing work." access:"unscoped_admin" mutation:"true" admin:"repo-add" bytes:"131072" check:"repo_list"`
	RepoArchive         Binding[RepoArchiveArgs, Repository]             `tool:"repo_archive" summary:"Archive a repository to stop new work." desc:"Archive a repository to stop accepting new work while retaining its records. Use repo_list to inspect its archived state." access:"unscoped_admin" mutation:"true" check:"repo_list"`
	RepoList            Binding[RepoListArgs, RepoPage]                  `tool:"repo_list" summary:"List registered repositories and their latest runs." desc:"Discover repositories visible to this caller and their registration state. Select the returned canonical name for later run or promotion calls." get:"/api/repos"`
	RepoRemove          Binding[RepoRemoveArgs, Receipt]                 `tool:"repo_remove" summary:"Remove a registered repository with an audit reason." desc:"Remove a repository registration after its lifecycle has been reviewed. Refresh repo_list before choosing further work." access:"unscoped_admin" mutation:"true" check:"repo_list"`
	RepoUnarchive       Binding[RepoUnarchiveArgs, Repository]           `tool:"repo_unarchive" summary:"Reactivate an archived repository registration." desc:"Reactivate an archived repository registration. Use repo_verify before submitting new work." access:"unscoped_admin" mutation:"true" check:"repo_list"`
	RepoVerify          Binding[RepoVerifyArgs, Repository]              `tool:"repo_verify" summary:"Verify repository upstream access and configuration." desc:"Probe source access for a registered repository without submitting a run. Correct the reported access problem before pushing work." access:"unscoped_admin" admin:"repo-verify" bytes:"131072"`
	UplinkAdd           Binding[UplinkAddArgs, Identity]                 `tool:"uplink_add" summary:"Create an uplink identity." desc:"Register a caller identity and its public key or certificate request. Install returned credentials locally before reconnecting." access:"unscoped_admin" mutation:"true" admin:"uplink-add" bytes:"131072" check:"uplink_list"`
	UplinkCert          Binding[UplinkCertArgs, Identity]                `tool:"uplink_cert" summary:"Issue a certificate for a registered identity." desc:"Issue a certificate for a registered caller using its signing request. Install the returned public certificate beside the retained private key." access:"unscoped_admin" mutation:"true" check:"uplink_list"`
	UplinkInvite        Binding[UplinkInviteArgs, model.Invitation]      `tool:"uplink_invite" command:"invite" flow:"true" summary:"Create a scoped invitation for a new caller." desc:"Create an invitation bound to an approved identity and repository scope. Deliver its locally retained private handoff to the recipient." access:"unscoped_admin" mutation:"true" check:"uplink_list"`
	UplinkList          Binding[UplinkListArgs, IdentityPage]            `tool:"uplink_list" summary:"List registered caller identities and their scopes." desc:"List registered caller identities and their public credential state. Inspect identity and scope before rotating or revoking credentials." access:"unscoped_admin" get:"/api/uplinks"`
	UplinkRevoke        Binding[UplinkRevokeArgs, Receipt]               `tool:"uplink_revoke" summary:"Revoke the selected registered caller identity." desc:"Revoke the selected registered caller identity. Use uplink_list to confirm its credentials can no longer be used." access:"unscoped_admin" mutation:"true" check:"uplink_list"`
	UplinkRotate        Binding[UplinkRotateArgs, Identity]              `tool:"uplink_rotate" summary:"Rotate an uplink credential." desc:"Rotate a registered caller credential after confirming the replacement public material. Install the replacement and inspect uplink_list." access:"unscoped_admin" mutation:"true" check:"uplink_list"`
	UplinkScope         Binding[UplinkScopeArgs, Identity]               `tool:"uplink_scope" summary:"Change the repository scope of a caller identity." desc:"Replace the repository scope of a registered caller identity. Use uplink_list to confirm the resulting authority." access:"unscoped_admin" mutation:"true" admin:"uplink-scope" bytes:"131072" check:"uplink_list"`
	UpstreamAdd         Binding[UpstreamAddArgs, Upstream]               `tool:"upstream_add" summary:"Register an upstream and its access configuration." desc:"Register a named upstream and its public trust configuration. Use upstream_list to inspect access before registering repositories." access:"unscoped_admin" mutation:"true" admin:"upstream-add" bytes:"131072" check:"upstream_list"`
	UpstreamList        Binding[UpstreamListArgs, UpstreamPage]          `tool:"upstream_list" summary:"Read registered upstreams and their public access state." desc:"Read registered upstreams and their public access state. Use the selected name when adding or verifying a repository." access:"unscoped_admin" admin:"upstream-list" bytes:"131072"`
	UpstreamProvideKey  Binding[UpstreamProvideKeyArgs, Upstream]        `tool:"upstream_provide_key" summary:"Provide a private key for upstream access." desc:"Import an upstream private key through an authenticated body. Use upstream_list to probe its public identity and access." access:"unscoped_admin" mutation:"true" admin:"upstream-provide-key" bytes:"131072" check:"upstream_list"`
	UpstreamRemove      Binding[UpstreamRemoveArgs, Receipt]             `tool:"upstream_remove" summary:"Remove an upstream registration." desc:"Remove a registered upstream after its dependent repositories have been reviewed. Refresh upstream_list to confirm remaining registrations." access:"unscoped_admin" mutation:"true" admin:"upstream-remove" bytes:"131072" check:"upstream_list"`
}
